use std::env;

fn main() {
    let Some(text) = env::args().nth(1).expect("Please provide a text argument") else {
        std::process::exit(2);
    };
    // Count non-empty lines. An empty line has no characters.
    // Spaces and tabs inside a line count as non-empty data.
    let lines = text.split('\n');
    let count = lines.iter()
        .filter(|line| !line.trim().is_empty())
        .count();
    println!("{}", count);
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_count_lines() {
        // Test with a multi-line string including blank lines and leading/trailing whitespace.
        let text = "hello\n\nworld\n   \ntabs\there\n";
        assert_eq!(count_lines(text), 3); // "hello", "world", "tabs\there"
    }
}

fn count_lines(text: &str) -> usize {
    let lines = text.split('\n');
    lines.iter().filter(|line| !line.trim().is_empty()).count()
}
